    ('DEFGIJKL', 'D', 'F', 'E', 'K', 'J', 'I', 'G', 'L'),
    ('DEFHIJKL', 'D', 'F', 'E', 'K', 'I', 'H', 'J', 'L'),
    ('DEGHIJKL', 'D', 'G', 'E', 'K', 'I', 'H', 'J', 'L'),
    ('DFGHIJKL', 'D', 'G', 'F', 'K', 'I', 'H', 'J', 'L'),
    ('EFGHIJKL', 'F', 'G', 'E', 'K', 'I', 'H', 'J', 'L')
),
group_matches as (
  select
    m.*,
    coalesce(m.group_name, gt_home.group_name) as inferred_group
  from public.matches m
  left join group_teams gt_home
    on gt_home.team = m.home_team
  left join group_teams gt_away
    on gt_away.team = m.away_team
   and gt_away.group_name = gt_home.group_name
  where m.stage = 'group'
    and gt_away.group_name is not null
),
readiness as (
  select
    count(*) as group_match_count,
    count(*) filter (
      where status = 'finished'
        and home_score is not null
        and away_score is not null
    ) as finished_with_scores
  from group_matches
),
team_rows as (
  select
    inferred_group as group_name,
    home_team as team,
    case when home_score > away_score then 3 when home_score = away_score then 1 else 0 end as points,
    home_score as goals_for,
    away_score as goals_against
  from group_matches
  where status = 'finished'
    and home_score is not null
    and away_score is not null
  union all
  select
    inferred_group as group_name,
    away_team as team,
    case when away_score > home_score then 3 when away_score = home_score then 1 else 0 end as points,
    away_score as goals_for,
    home_score as goals_against
  from group_matches
  where status = 'finished'
    and home_score is not null
    and away_score is not null
),
standings as (
  select
    group_name,
    team,
    count(*) as played,
    sum(points) as points,
    sum(goals_for) as goals_for,
    sum(goals_against) as goals_against,
    sum(goals_for) - sum(goals_against) as goal_difference
  from team_rows
  group by group_name, team
),
ranked as (
  select
    *,
    row_number() over (
      partition by group_name
      order by points desc, goal_difference desc, goals_for desc, team asc
    ) as group_rank
  from standings
),
group_top as (
  select
    group_name,
    max(team) filter (where group_rank = 1) as first_team,
    max(team) filter (where group_rank = 2) as second_team,
    max(team) filter (where group_rank = 3) as third_team
  from ranked
  group by group_name
),
best_thirds as (
  select *
  from ranked
  where group_rank = 3
  order by points desc, goal_difference desc, goals_for desc, team asc
  limit 8
),
best_key as (
  select string_agg(group_name, '' order by group_name) as combination_key
  from best_thirds
),
matched_third_map as (
  select third_map.*
  from third_map
  join best_key using (combination_key)
),
third_assignment(slot, group_name) as (
  select 'T1', t1 from matched_third_map union all
  select 'T2', t2 from matched_third_map union all
  select 'T3', t3 from matched_third_map union all
  select 'T4', t4 from matched_third_map union all
  select 'T5', t5 from matched_third_map union all
  select 'T6', t6 from matched_third_map union all
  select 'T7', t7 from matched_third_map union all
  select 'T8', t8 from matched_third_map
),
third_slot_teams as (
  select
    third_assignment.slot,
    ranked.team
  from third_assignment
  join ranked
    on ranked.group_name = third_assignment.group_name
   and ranked.group_rank = 3
),
updates as (
  select 73 as match_number, 'Group A runners-up' as placeholder_home, 'Group B runners-up' as placeholder_away, (select second_team from group_top where group_name = 'A') as home_team, (select second_team from group_top where group_name = 'B') as away_team
  union all
  select 74 as match_number, 'Group E winners' as placeholder_home, 'Group A/B/C/D/F third place' as placeholder_away, (select first_team from group_top where group_name = 'E') as home_team, (select team from third_slot_teams where slot = 'T1') as away_team
  union all
  select 75 as match_number, 'Group F winners' as placeholder_home, 'Group C runners-up' as placeholder_away, (select first_team from group_top where group_name = 'F') as home_team, (select second_team from group_top where group_name = 'C') as away_team
  union all
  select 76 as match_number, 'Group C winners' as placeholder_home, 'Group F runners-up' as placeholder_away, (select first_team from group_top where group_name = 'C') as home_team, (select second_team from group_top where group_name = 'F') as away_team
  union all
  select 77 as match_number, 'Group I winners' as placeholder_home, 'Group C/D/F/G/H third place' as placeholder_away, (select first_team from group_top where group_name = 'I') as home_team, (select team from third_slot_teams where slot = 'T2') as away_team
  union all
  select 78 as match_number, 'Group E runners-up' as placeholder_home, 'Group I runners-up' as placeholder_away, (select second_team from group_top where group_name = 'E') as home_team, (select second_team from group_top where group_name = 'I') as away_team
  union all
  select 79 as match_number, 'Group A winners' as placeholder_home, 'Group C/E/F/H/I third place' as placeholder_away, (select first_team from group_top where group_name = 'A') as home_team, (select team from third_slot_teams where slot = 'T3') as away_team
  union all
  select 80 as match_number, 'Group L winners' as placeholder_home, 'Group E/H/I/J/K third place' as placeholder_away, (select first_team from group_top where group_name = 'L') as home_team, (select team from third_slot_teams where slot = 'T4') as away_team
  union all
  select 81 as match_number, 'Group D winners' as placeholder_home, 'Group B/E/F/I/J third place' as placeholder_away, (select first_team from group_top where group_name = 'D') as home_team, (select team from third_slot_teams where slot = 'T5') as away_team
  union all
  select 82 as match_number, 'Group G winners' as placeholder_home, 'Group A/E/H/I/J third place' as placeholder_away, (select first_team from group_top where group_name = 'G') as home_team, (select team from third_slot_teams where slot = 'T6') as away_team
  union all
  select 83 as match_number, 'Group K runners-up' as placeholder_home, 'Group L runners-up' as placeholder_away, (select second_team from group_top where group_name = 'K') as home_team, (select second_team from group_top where group_name = 'L') as away_team
  union all
  select 84 as match_number, 'Group H winners' as placeholder_home, 'Group J runners-up' as placeholder_away, (select first_team from group_top where group_name = 'H') as home_team, (select second_team from group_top where group_name = 'J') as away_team
  union all
  select 85 as match_number, 'Group B winners' as placeholder_home, 'Group E/F/G/I/J third place' as placeholder_away, (select first_team from group_top where group_name = 'B') as home_team, (select team from third_slot_teams where slot = 'T7') as away_team
  union all
  select 86 as match_number, 'Group J winners' as placeholder_home, 'Group H runners-up' as placeholder_away, (select first_team from group_top where group_name = 'J') as home_team, (select second_team from group_top where group_name = 'H') as away_team
  union all
  select 87 as match_number, 'Group K winners' as placeholder_home, 'Group D/E/I/J/L third place' as placeholder_away, (select first_team from group_top where group_name = 'K') as home_team, (select team from third_slot_teams where slot = 'T8') as away_team
  union all
  select 88 as match_number, 'Group D runners-up' as placeholder_home, 'Group G runners-up' as placeholder_away, (select second_team from group_top where group_name = 'D') as home_team, (select second_team from group_top where group_name = 'G') as away_team
),
targets as (
  select
    m.id,
    updates.match_number,
    updates.home_team,
    updates.away_team,
    m.home_team as previous_home_team,
    m.away_team as previous_away_team
  from public.matches m
  join updates
    on (
      m.match_number = updates.match_number
      or (
        m.match_number is null
        and lower(trim(m.home_team)) = lower(trim(updates.placeholder_home))
        and lower(trim(m.away_team)) = lower(trim(updates.placeholder_away))
      )
    )
  where m.stage = 'round_of_32'
)

select
  readiness.group_match_count,
  readiness.finished_with_scores,
  (select combination_key from best_key) as best_third_combination,
  (select count(*) from targets) as target_rows
from readiness;

